\Delta \overline{x}(t) &= \int_{0^-}^{t} \frac{d\overline{x}_\mathrm{evo}}{dt} dt + \int_{0^-}^{t} \frac{d\overline{x}_\mathrm{plas}}{dt} dt \nonumber \\
&= \Delta \overline{x}_\mathrm{evo}(t) + \Delta \overline{x}_\mathrm{plas} \nonumber \\
&= -\frac{F_{xy}}{F_{xx}} \Delta \overline{y} (t) + \Delta \overline{x}_\mathrm{plas}

\Delta \overline{x}_\mathrm{total} &= \Delta \overline{x}_\mathrm{evo}(\infty) + \Delta \overline{x}_\mathrm{plas} \nonumber \\
&= - \frac{F_{xy}}{F_{xx}} \Delta \overline{y}(\infty) + \Delta \overline{x}_\mathrm{plas} \nonumber \\
&= \left(1 + \frac{F_{xy}^2}{\det H} \right) \Delta \overline{x}_\mathrm{plas}

G_{yy} &= \frac{G_{yy}}{1 + \kappa G_{yy}} + V_m \nonumber \\
0 &= \kappa G_{yy}^2 - \kappa V_m G_{yy} - V_m \nonumber \\
G_{yy} &= \frac{V_m}{2} + \sqrt{\frac{V_{m}^2}{4} + \frac{V_m}{\kappa}}
